local function dumpInstance(instance, log, indent)
    indent = indent or S(156)
    for _, child in ipairs(instance:GetChildren()) do
        local line = indent .. child.ClassName .. S(134) .. child.Name .. S(168)
        if child:IsA(S(113)) then
            line = line .. string.format(
                S(61),
                child.ActionText, child.ObjectText, tostring(child.HoldDuration)
            )
        elseif child:IsA(S(63)) then
            line = line .. string.format(S(19), tostring(child.MaxActivationDistance))
        elseif child:IsA(S(200)) or child:IsA(S(16)) then
            line = line .. S(36)
        end
        log(line)
        dumpInstance(child, log, indent .. S(157))
    end
end
return dumpInstance
end
